    vocabulary: [["Guild","(Noun) An association of craftspeople or merchants."],["Gatekeeping","(Noun) Controlling access to a community or field."],["Intergenerational","(Adjective) Spanning multiple age generations."],["Porosity","(Noun) Quality of allowing movement in and out."],["Subsidised","(Adjective) Supported financially to reduce cost."],["Pipeline","(Noun) A channel supplying new participants."],["Tacit","(Adjective) Known through practice, hard to put in words."],["Solidarity","(Noun) Mutual support among groups with shared interests."],["Niche","(Noun) A specialised segment."],["Infrastructure","(Noun) Basic systems enabling activity."],["Ritual","(Noun) A regular meaningful practice."],["Drift","(Verb) To move away gradually from a path or group."],["Contributor","(Noun) One who adds effort or knowledge to a community."],["Elder","(Noun) A respected experienced member."],["Norm","(Noun) An expected standard of behaviour."],["Heroic","(Adjective) Requiring extraordinary individual effort."]],
